    /** Manual setup: focus, dates and the ordered workouts that repeat until the target is reached. Four calendar months by default. */
    void edit(String id){JSONObject found=id==null?null:WorkoutStore.data(a,"sprint",id);JSONObject base;try{base=found==null?new JSONObject().put("status","active"):new JSONObject(found.toString());}catch(JSONException e){return;}final JSONObject d=base;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,id==null?"Set up a sprint":"Edit sprint");EditText name=ui.field("Name",d.optString("name",""));s.body.addView(name,WorkoutViews.gap(ui,8));final String[] phase={d.optString("phase",PHASES[0])};Button pick=ui.quietButton("Focus: "+phase[0],null);pick.setOnClickListener(v->new AlertDialog.Builder(a).setItems(PHASES,(x,i)->{phase[0]=PHASES[i];pick.setText("Focus: "+phase[0]);}).show());s.body.addView(pick,WorkoutViews.gap(ui,8));LocalDate today=LocalDate.now();EditText start=ui.field("Start, YYYY-MM-DD",d.optString("start",today.toString())),end=ui.field("End, YYYY-MM-DD",d.optString("end",today.plusMonths(4).toString())),target=ui.field("Target workouts",d.has("target_sessions")?""+d.optInt("target_sessions"):"48");target.setInputType(InputType.TYPE_CLASS_NUMBER);s.body.addView(start,WorkoutViews.gap(ui,8));s.body.addView(end,WorkoutViews.gap(ui,8));s.body.addView(target,WorkoutViews.gap(ui,8));EditText goals=ui.field("Success criteria, one per line",join(d.optJSONArray("success_criteria")));goals.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);goals.setSingleLine(false);goals.setMinLines(2);s.body.addView(goals,WorkoutViews.gap(ui,12));
        s.body.addView(ui.label("Workout cycle"),WorkoutViews.gap(ui,6));ArrayList<String> cycle=new ArrayList<>();JSONArray old=d.optJSONArray("cycle");for(int i=0;old!=null&&i<old.length();i++)cycle.add(old.optString(i));LinearLayout rows=ui.column();s.body.addView(rows);Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();for(int i=0;i<cycle.size();i++){final int at=i;JSONObject t=WorkoutStore.data(a,"template",cycle.get(i));rows.addView(WorkoutViews.row(ui,(i+1)+" · "+(t==null?"Removed template":t.optString("name")),"Tap to remove",()->{cycle.remove(at);paint[0].run();}),WorkoutViews.gap(ui,6));}};paint[0].run();List<JSONObject> t=templateRows();s.body.addView(ui.quietButton("Add a workout to the cycle",()->{String[] names=new String[t.size()];for(int i=0;i<names.length;i++)names[i]=t.get(i).optJSONObject("data").optString("name");new AlertDialog.Builder(a).setItems(names,(x,i)->{cycle.add(t.get(i).optString("id"));paint[0].run();}).show();}),WorkoutViews.gap(ui,12));
        s.body.addView(ui.primaryButton("Save sprint",()->{try{LocalDate first=LocalDate.parse(start.getText().toString().trim()),last=LocalDate.parse(end.getText().toString().trim());if(last.isBefore(first))throw new IllegalArgumentException();int goal=Integer.parseInt(target.getText().toString().trim());JSONArray criteria=new JSONArray();for(String line:goals.getText().toString().split("\n"))if(!line.trim().isEmpty())criteria.put(line.trim());JSONArray order=new JSONArray();for(String c:cycle)order.put(c);String title=name.getText().toString().trim();if(title.isEmpty())throw new IllegalArgumentException();d.put("name",title).put("phase",phase[0]).put("start",first.toString()).put("end",last.toString()).put("cycle",order).put("target_sessions",goal).put("success_criteria",criteria);WorkoutStore.put(a,"sprint",id==null?WorkoutStore.id():id,d);s.dialog.dismiss();screen.refresh();}catch(Exception e){Toast.makeText(a,"Check the name, dates and target",Toast.LENGTH_LONG).show();}}));s.show();}
    private static String join(JSONArray v){StringBuilder b=new StringBuilder();for(int i=0;v!=null&&i<v.length();i++)b.append(i==0?"":"\n").append(v.optString(i));return b.toString();}

