    /** Every planned set in order, expanded from a plain sets × reps prescription when the plan has no sets of its own. */
    static JSONArray sets(Context c,JSONObject p){JSONArray plan=p.optJSONArray("set_plan");if(plan!=null&&plan.length()>0)return plan;JSONArray out=new JSONArray();boolean run=WorkoutStore.cardio(c,p.optString("exercise_id"));try{for(int i=0;i<Math.max(1,p.optInt("sets",1));i++){JSONObject q=new JSONObject().put("kind",run?"warmup":"working");if(run){double m=p.optDouble("distance_m",0),v=p.optDouble("speed_kmh",0);if(m>0)q.put("distance_m",m);if(m>0&&v>0)q.put("seconds",Math.round(m/(v/3.6)));}else{if(!p.isNull("weight_kg"))q.put("weight_kg",p.optDouble("weight_kg"));if(p.optInt("min_reps")>0)q.put("reps",p.optInt("min_reps"));if(!p.isNull("rir"))q.put("rir",p.optDouble("rir"));}out.put(q);}}catch(JSONException ignored){}return out;}
    /** An exercise in a template, drawn with its sets so warm-ups and hard sets read at a glance. */
    private View planRow(JSONObject p,Runnable open){LinearLayout r=ui.row();r.setPadding(ui.dp(10),ui.dp(10),ui.dp(10),ui.dp(10));r.setBackground(ui.pressable(ui.outline(ui.surface,16,ui.stroke,1),16));String id=p.optString("exercise_id");r.addView(WorkoutArt.tile(ui,id,44),new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));LinearLayout w=ui.column();w.addView(ui.type(WorkoutStore.exerciseName(a,id),15,20,600,0,ui.text));LinearLayout marks=ui.row();JSONArray plan=sets(a,p);int number=0;for(int i=0;i<Math.min(9,plan.length());i++){String kind=plan.optJSONObject(i).optString("kind","working");if("working".equals(kind))number++;marks.addView(WorkoutViews.setTag(ui,kind,number),MainParts.params(ui,ui.dp(26),ui.dp(26),0,0,3,0));}w.addView(marks,MainParts.params(ui,-1,-2,0,4,0,0));r.addView(w,MainParts.weighted(ui,1,10,0,0,0));r.setOnClickListener(v->open.run());AppUi.press(r);return r;}
    private EditText cell(String value,String label,boolean decimal){EditText v=new EditText(a);v.setText(value);v.setTextSize(15);v.setTypeface(AppUi.face(600));v.setTextColor(ui.text);v.setGravity(Gravity.CENTER);v.setPadding(0,0,0,0);v.setSingleLine(true);v.setSelectAllOnFocus(true);v.setContentDescription(label);v.setInputType(decimal?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL:InputType.TYPE_CLASS_NUMBER);v.setBackground(ui.outline(ui.surfaceAlt,10,0,0));return v;}
    /** The exercise's sets, edited the way they are logged: tap a number to change its type, swipe left to delete. Saved on the way back. */
    private void prescription(JSONArray list,int index,Runnable after){JSONObject p=list.optJSONObject(index);String id=p.optString("exercise_id");boolean run=WorkoutStore.cardio(a,id);WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,WorkoutStore.exerciseName(a,id));JSONArray plan;try{plan=new JSONArray(sets(a,p).toString());}catch(JSONException e){return;}boolean[] removed={false};s.bar.addView(ui.iconButton("trash","Remove exercise",ui.hue(AppUi.RED),()->{removed[0]=true;list.remove(index);s.dialog.dismiss();}),new LinearLayout.LayoutParams(ui.dp(46),ui.dp(46)));LinearLayout rows=ui.column();s.body.addView(rows);Runnable[] paint=new Runnable[1];paint[0]=()->{rows.removeAllViews();int number=0;for(int i=0;i<plan.length();i++){final int at=i;JSONObject q=plan.optJSONObject(i);String kind=q.optString("kind","working");if("working".equals(kind))number++;LinearLayout r=new WorkoutViews.SwipeRow(ui,()->{plan.remove(at);paint[0].run();});r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(0,ui.dp(3),0,ui.dp(3));TextView tag=WorkoutViews.setTag(ui,kind,number);tag.setOnClickListener(v->{List<String> order=Arrays.asList("working","warmup","drop","failure");try{q.put("kind",order.get((order.indexOf(q.optString("kind","working"))+1)%order.size()));}catch(JSONException ignored){}v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);paint[0].run();});r.addView(tag,MainParts.params(ui,ui.dp(34),ui.dp(38),0,0,8,0));EditText first=cell(run?(q.optDouble("distance_m",0)>0?WorkoutUnits.distanceNumber(a,q.optDouble("distance_m")):""):q.isNull("weight_kg")?"":WorkoutUnits.loadNumber(a,q.optDouble("weight_kg")),run?"Distance":"Weight",true),second=cell(run?(q.optLong("seconds")>0?String.valueOf(q.optLong("seconds")/60):""):q.optInt("reps")>0?String.valueOf(q.optInt("reps")):"",run?"Minutes":"Reps",false);first.setHint(run?WorkoutUnits.distanceLabel(a):WorkoutUnits.loadLabel(a));second.setHint(run?"min":"reps");first.setHintTextColor(ui.muted);second.setHintTextColor(ui.muted);first.addTextChangedListener(new WorkoutLive.Watch(t->{try{if(t.trim().isEmpty())q.remove(run?"distance_m":"weight_kg");else{double v=Double.parseDouble(t.trim().replace(',','.'));if(run)q.put("distance_m",WorkoutUnits.distanceIn(a,v));else q.put("weight_kg",WorkoutUnits.loadIn(a,v));}}catch(Exception ignored){}}));second.addTextChangedListener(new WorkoutLive.Watch(t->{try{if(t.trim().isEmpty())q.remove(run?"seconds":"reps");else if(run)q.put("seconds",Integer.parseInt(t.trim())*60);else q.put("reps",Integer.parseInt(t.trim()));}catch(Exception ignored){}}));LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,ui.dp(42),1);half.setMarginEnd(ui.dp(6));r.addView(first,half);r.addView(second,new LinearLayout.LayoutParams(0,ui.dp(42),1));rows.addView(r);}};paint[0].run();s.body.addView(ui.ghostButton("Add set",()->{try{JSONObject q=plan.length()>0?new JSONObject(plan.getJSONObject(plan.length()-1).toString()):new JSONObject().put("kind","working");if("warmup".equals(q.optString("kind"))&&!run)q.put("kind","working");plan.put(q);paint[0].run();}catch(JSONException ignored){}}),WorkoutViews.gap(ui,10));WorkoutViews.Stepper rest=new WorkoutViews.Stepper(ui,p.optInt("rest_seconds",120),15,0,v->WorkoutViews.clock((long)v)+" rest");if(!run)s.body.addView(rest);s.dialog.setOnDismissListener(x->{if(!removed[0])commit(p,plan,(int)rest.value);after.run();});s.show();}
    /** The plain fields follow the set plan, so summaries and older clients stay right. */
    private void commit(JSONObject p,JSONArray plan,int rest){try{p.put("set_plan",plan).put("rest_seconds",rest);int low=1000,high=0,hard=0;double load=-1;for(int i=0;i<plan.length();i++){JSONObject q=plan.getJSONObject(i);if("warmup".equals(q.optString("kind")))continue;hard++;int r=q.optInt("reps");if(r>0){low=Math.min(low,r);high=Math.max(high,r);}if(load<0&&!q.isNull("weight_kg"))load=q.optDouble("weight_kg");}p.put("sets",Math.max(1,hard));if(high>0)p.put("min_reps",low).put("max_reps",high);if(load>=0)p.put("weight_kg",load);JSONObject first=plan.length()>0?plan.getJSONObject(0):null;if(first!=null&&first.optDouble("distance_m",0)>0){p.put("distance_m",first.optDouble("distance_m"));if(first.optLong("seconds")>0){p.put("estimated_seconds",first.optLong("seconds"));p.put("speed_kmh",first.optDouble("distance_m")/first.optLong("seconds")*3.6);}}}catch(JSONException ignored){}}
    /** After a session that differed: the template takes this session's exercises and set counts. Prescribed loads are kept. */
    void saveStructure(String id,JSONObject template,JSONArray used){new AlertDialog.Builder(a).setTitle("Update the template?").setMessage("Future sessions from this template will use today's exercises and sets. Past sessions don't change.").setPositiveButton("Update template",(x,w)->{try{JSONObject t=new JSONObject(template.toString());JSONArray old=t.optJSONArray("exercises"),next=new JSONArray();for(int i=0;i<used.length();i++){JSONObject u=used.getJSONObject(i);JSONObject p=null;for(int k=0;old!=null&&k<old.length();k++)if(u.optString("eid").equals(old.getJSONObject(k).optString("exercise_id")))p=new JSONObject(old.getJSONObject(k).toString());if(p==null)p=new JSONObject().put("exercise_id",u.optString("eid")).put("min_reps",8).put("max_reps",12).put("rest_seconds",u.optInt("rest",120));JSONArray rows=u.getJSONArray("sets"),plan=new JSONArray();int hard=0;for(int k=0;k<rows.length();k++){JSONObject set=rows.getJSONObject(k),q=new JSONObject().put("kind",set.optString("kind","working"));if(!"warmup".equals(q.optString("kind")))hard++;if(set.has("weight"))q.put("weight_kg",set.optDouble("weight"));if(set.has("reps"))q.put("reps",set.optInt("reps"));if(set.has("rir"))q.put("rir",set.optDouble("rir"));if(set.has("distance"))q.put("distance_m",set.optDouble("distance"));if(set.has("seconds"))q.put("seconds",set.optLong("seconds"));plan.put(q);}p.put("sets",Math.max(1,hard)).put("set_plan",plan);next.put(p);}t.put("exercises",next);WorkoutStore.put(a,"template",id,t);Toast.makeText(a,"Template updated",Toast.LENGTH_SHORT).show();}catch(JSONException ignored){}}).setNegativeButton("Keep template",null).show();}

    /** The catalog as a picture grid: filter by movement or search, or have the coach create what's missing. */
    static void pick(WorkoutScreen screen,Consumer<String> chosen){AppUi ui=screen.ui;MainActivity a=screen.a;WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Choose exercise");EditText search=ui.field("Search exercises","");search.setTag("exercise_search");s.body.addView(search,WorkoutViews.gap(ui,8));List<JSONObject> all=WorkoutStore.rows(a,"exercise");Collections.sort(all,(x,y)->x.optJSONObject("data").optString("name").compareToIgnoreCase(y.optJSONObject("data").optString("name")));String[] filter={""};LinearLayout chips=ui.row();HorizontalScrollView strip=new HorizontalScrollView(a);strip.setHorizontalScrollBarEnabled(false);strip.addView(chips);s.body.addView(strip,WorkoutViews.gap(ui,10));LinearLayout grid=ui.column();s.body.addView(grid);Runnable[] paint=new Runnable[1];paint[0]=()->{chips.removeAllViews();TreeSet<String> groups=new TreeSet<>();for(JSONObject r:all)groups.add(WorkoutArt.group(r.optJSONObject("data")));ArrayList<String> names=new ArrayList<>();names.add("");names.addAll(groups);for(String g:names){boolean on=g.equals(filter[0]);int hue=g.isEmpty()?ui.accent:WorkoutArt.hue(ui,g);TextView c=ui.type(g.isEmpty()?"All":g,13,18,700,0,on?ui.onAccent:hue);c.setGravity(Gravity.CENTER);c.setPadding(ui.dp(14),ui.dp(7),ui.dp(14),ui.dp(7));c.setBackground(ui.outline(on?hue:AppUi.alpha(hue,.16f),14,0,0));c.setOnClickListener(v->{filter[0]=g;paint[0].run();});chips.addView(c,MainParts.params(ui,-2,-2,0,0,6,0));}grid.removeAllViews();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);LinearLayout row=null;int count=0;for(JSONObject r:all){JSONObject d=r.optJSONObject("data");if(!q.isEmpty()&&!d.optString("name").toLowerCase(Locale.ROOT).contains(q))continue;if(!filter[0].isEmpty()&&!filter[0].equals(WorkoutArt.group(d)))continue;if(count++%3==0){row=ui.row();row.setGravity(Gravity.TOP);grid.addView(row,WorkoutViews.gap(ui,6));}LinearLayout cell=ui.column();cell.setGravity(Gravity.CENTER_HORIZONTAL);cell.setPadding(ui.dp(4),ui.dp(6),ui.dp(4),ui.dp(6));cell.addView(new WorkoutArt.Tile(ui,d),new LinearLayout.LayoutParams(ui.dp(68),ui.dp(68)));TextView name=ui.type(d.optString("name"),12,16,600,0,ui.text);name.setGravity(Gravity.CENTER);name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);cell.addView(name,MainParts.params(ui,-1,-2,0,4,0,0));cell.setOnClickListener(v->{s.dialog.dismiss();chosen.accept(r.optString("id"));});AppUi.press(cell);row.addView(cell,new LinearLayout.LayoutParams(0,-2,1));}if(row!=null)while(count++%3!=0)row.addView(new View(a),new LinearLayout.LayoutParams(0,1,1));};paint[0].run();search.addTextChangedListener(new TextWatcher(){public void afterTextChanged(Editable e){paint[0].run();}public void beforeTextChanged(CharSequence c,int x,int y,int z){}public void onTextChanged(CharSequence c,int x,int y,int z){}});
        LinearLayout tools=ui.row();tools.addView(ui.quietButton("New exercise",()->{EditText name=ui.field("Exercise name",search.getText().toString().trim());Switch cardio=new Switch(a);cardio.setText("Timed distance, such as a run");LinearLayout box=ui.column();box.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),0);box.addView(name,WorkoutViews.gap(ui,8));box.addView(cardio);new AlertDialog.Builder(a).setTitle("New exercise").setView(box).setPositiveButton("Add",(x,i)->{String v=name.getText().toString().trim();if(v.isEmpty())return;try{String id=WorkoutStore.id();WorkoutStore.put(a,"exercise",id,new JSONObject().put("name",v).put("mode",cardio.isChecked()?"cardio":"strength"));s.dialog.dismiss();chosen.accept(id);}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}),new LinearLayout.LayoutParams(0,-2,1));tools.addView(ui.iconButton("sparkle","Ask your coach to create an exercise",ui.hue(AppUi.VIOLET),()->{String wanted=search.getText().toString().trim();s.dialog.dismiss();try{screen.coach.open(new JSONObject().put("purpose","new_exercise"),null,"Create a new exercise"+(wanted.isEmpty()?": ":": "+wanted));}catch(JSONException ignored){}}),MainParts.params(ui,ui.dp(48),ui.dp(48),8,0,0,0));s.body.addView(tools,MainParts.params(ui,-1,-2,0,8,0,0));s.show();}

    /** Today only: another sprint day, edited exercises, a shorter session, or rest. The sprint plan stays and the change goes to the review. */
    void change(JSONObject next){WorkoutViews.Sheet s=new WorkoutViews.Sheet(ui,"Change today's workout");JSONObject sprint=next.optJSONObject("sprint");String sid=sprint==null?null:sprint.optString("id"),date=next.optString("date"),current=next.optString("template_id");JSONObject t=WorkoutStore.data(a,"template",current);String name=t==null?"Session":t.optString("name");s.body.addView(ui.label("Swap with another session"),WorkoutViews.gap(ui,6));HashSet<String> seen=new HashSet<>();JSONArray plan=sprint==null?null:sprint.optJSONObject("data").optJSONArray("cycle");for(int i=0;plan!=null&&i<plan.length();i++){String tid=plan.optString(i);if(tid.equals(current)||!seen.add(tid))continue;JSONObject other=WorkoutStore.data(a,"template",tid);if(other==null)continue;s.body.addView(WorkoutViews.row(ui,other.optString("name"),"Do this instead today",()->{s.dialog.dismiss();screen.begin(other.optString("name"),tid,sid,date,change("swap_day","Swapped "+name+" for "+other.optString("name"),date));}),WorkoutViews.gap(ui,8));}
        s.body.addView(ui.label("Or"),MainParts.params(ui,-1,-2,0,8,0,6));s.body.addView(WorkoutViews.row(ui,"Edit exercises for today","Starts the session; change anything as you go",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("edit_exercises","Chose to edit today's exercises",date));}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Shorter session","Keeps the first half of the exercises",()->{s.dialog.dismiss();screen.begin(name,current,sid,date,change("shorter","Shortened the session",date));JSONObject d=WorkoutStore.draft(a);if(d!=null&&screen.live!=null){JSONArray ex=d.optJSONArray("exercises");for(int i=ex.length()-1;i>=Math.max(1,(ex.length()+1)/2);i--)ex.remove(i);WorkoutStore.saveDraft(a,d);screen.live.d=d;screen.live.render();}}),WorkoutViews.gap(ui,8));s.body.addView(WorkoutViews.row(ui,"Rest today","Never counts against the sprint",()->rest(s,name,current,sid,date)),WorkoutViews.gap(ui,10));s.body.addView(ui.detail("Changes apply to today only and are noted for your sprint review."));s.show();}
    JSONObject change(String kind,String reason,String date){try{return new JSONObject().put("id",WorkoutStore.id()).put("at",OffsetDateTime.now().withNano(0).toString()).put("kind",kind).put("reason",reason).put("original_date",date);}catch(JSONException e){throw new IllegalStateException(e);}}
    private void rest(WorkoutViews.Sheet s,String name,String template,String sprint,String date){EditText why=ui.field("Why, such as still sore","");new AlertDialog.Builder(a).setTitle("Rest today?").setView(why).setPositiveButton("Rest",(x,i)->{try{String reason=why.getText().toString().trim();JSONObject w=new JSONObject().put("name",name).put("started_at",OffsetDateTime.now().withNano(0).toString()).put("timezone",ZoneId.systemDefault().getId()).put("status","skipped").put("recovery_adjusted",true).put("skip_reason",reason.isEmpty()?"Rest day":reason).put("template_id",template).put("session_changes",new JSONArray().put(change("rest_move",reason.isEmpty()?"Rest day":reason,date))).put("source",new JSONObject().put("companion",new JSONObject().put("scheduled_date",date)));if(sprint!=null)w.put("sprint_id",sprint);WorkoutStore.put(a,"workout",WorkoutStore.id(),w);s.dialog.dismiss();screen.refresh();}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();}
